def summarize_incident(error_logs: List[Dict]) -> str:
    client = get_anthropic_client()

    log_messages = [log.get("@message", "") for log in error_logs]
    log_text = "\n".join(log_messages)

    if not log_text:
        return "No error logs provided for summarization."

    try:
        response = client.messages.create(
            model="claude-3-opus-20240229", # Using a powerful Claude 3 model for summarization
            max_tokens=1024,
            messages=[
                {"role": "user", "content": f"Please summarize the following error logs for an incident review. Focus on identifying the root cause, affected components, and potential impact:\n\n{log_text}"}
            ]
        )
        return response.content[0].text
    except Exception as e:
        print(f"Error summarizing incident: {e}")
        raise

from observability_client import get_cloudwatch_comprehend_client
from typing import List, Dict
import os

def check_log_text_safety(log_messages: List[str]) -> Dict[str, Any]:
    client = get_cloudwatch_comprehend_client()

    safety_results = {}
    for i, message in enumerate(log_messages):
        if not message.strip():
            safety_results[f"log_message_{i}"] = {"status": "empty_message", "findings": []}
            continue

        try:
            # Detects personally identifiable information (PII)
            pii_response = client.detect_pii_entities(Text=message, LanguageCode="en")

            # Detects sentiment (could indicate distress or anger)
            sentiment_response = client.detect_sentiment(Text=message, LanguageCode="en")

            # Detects toxic content if a custom model is trained and deployed, otherwise using general capabilities
            # For a general safety check, we can infer from sentiment and PII presence

            findings = []
            if pii_response["Entities"]:
                findings.append({"type": "PII_DETECTED", "details": pii_response["Entities"]})

            if sentiment_response["Sentiment"] in ["NEGATIVE", "MIXED"]:
                findings.append({"type": "SENTIMENT_WARNING", "details": sentiment_response["Sentiment"], "sentiment_scores": sentiment_response["SentimentScore"]})

            safety_results[f"log_message_{i}"] = {"status": "checked", "findings": findings}
        except client.exceptions.TextSizeLimitExceededException:
            safety_results[f"log_message_{i}"] = {"status": "skipped", "reason": "Text size limit exceeded for Comprehend", "findings": []}
        except Exception as e:
            safety_results[f"log_message_{i}"] = {"status": "error", "error": str(e), "findings": []}
    return safety_results

from observability_client import get_cloudwatch_translate_client
from typing import List, Dict
import os

def translate_log_messages(log_messages: List[str], target_language_code: str = "es", source_language_code: str = "en") -> Dict[str, str]:
    client = get_cloudwatch_translate_client()

    translated_messages = {}
    for i, message in enumerate(log_messages):
        if not message.strip():
            translated_messages[f"log_message_{i}"] = ""
            continue

        try:
            response = client.translate_text(
                Text=message,
                SourceLanguageCode=source_language_code,
                TargetLanguageCode=target_language_code
            )
            translated_messages[f"log_message_{i}"] = response["TranslatedText"]
        except Exception as e:
            print(f"Error translating log message {i}: {e}")
            translated_messages[f"log_message_{i}"] = f"Translation_Error: {e}"
    return translated_messages

from observability_client import get_openai_client
from typing import List, Dict
import os

def embed_log_messages(log_messages: List[str], model: str = "text-embedding-ada-002") -> Dict[str, List[float]]:
    client = get_openai_client()

    embeddings = {}
    for i, message in enumerate(log_messages):
        if not message.strip():
            embeddings[f"log_message_{i}"] = []
            continue

        try:
            response = client.embeddings.create(
                input=message,
                model=model
            )
            embeddings[f"log_message_{i}"] = response.data[0].embedding
        except Exception as e:
            print(f"Error embedding log message {i}: {e}")
            embeddings[f"log_message_{i}"] = [] # Return empty list on error
    return embeddings
